import { beforeEach, describe, expect, mock, test } from "bun:test";
import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import ProfileSelect from "@/components/menu/ProfileSelect";
import { createProfile, readProfiles } from "@/lib/game/profiles";

beforeEach(() => localStorage.clear());

describe("ProfileSelect", () => {
  test("lists existing profiles and plays the chosen one", async () => {
    const user = userEvent.setup();
    const alice = createProfile("Alice", "alex");
    createProfile("Bob", "robot");
    const onPlay = mock();
    render(<ProfileSelect onPlay={onPlay} />);

    expect(screen.getByText("Alice")).toBeTruthy();
    expect(screen.getByText("Bob")).toBeTruthy();

    await user.click(screen.getByTestId(`profile-${alice.id}`));
    expect(onPlay).toHaveBeenCalledWith(alice.id);
  });

  test("with no profiles it opens straight into the create form (no cancel)", () => {
    render(<ProfileSelect onPlay={mock()} />);
    expect(screen.getByText("Create Your Profile")).toBeTruthy();
    expect(screen.getByLabelText("Profile name")).toBeTruthy();
    expect(screen.queryByRole("button", { name: "Cancel" })).toBeNull();
  });

  test("first-run create enters the new profile", async () => {
    const user = userEvent.setup();
    const onPlay = mock();
    render(<ProfileSelect onPlay={onPlay} />);
    await user.type(screen.getByLabelText("Profile name"), "Solo");
    await user.click(screen.getByRole("button", { name: "Create" }));
    const created = readProfiles().profiles.find((p) => p.name === "Solo")!;
    expect(onPlay).toHaveBeenCalledWith(created.id);
  });

  test("adding another profile from the list persists it and enters it", async () => {
    const user = userEvent.setup();
    createProfile("Existing", "default"); // so the list (not the first-run form) renders
    const onPlay = mock();
    render(<ProfileSelect onPlay={onPlay} />);

    await user.click(screen.getByTestId("new-profile"));
    await user.type(screen.getByLabelText("Profile name"), "Charlie");
    await user.click(screen.getByRole("button", { name: "Create" }));

    const profiles = readProfiles().profiles;
    expect(profiles.map((p) => p.name)).toContain("Charlie");
    const created = profiles.find((p) => p.name === "Charlie")!;
    expect(onPlay).toHaveBeenCalledWith(created.id);
  });

  test("deleting a profile removes it after confirmation", async () => {
    const user = userEvent.setup();
    createProfile("Doomed", "default");
    render(<ProfileSelect onPlay={mock()} />);

    await user.click(screen.getByRole("button", { name: "Delete" }));
    await user.click(screen.getByRole("button", { name: "Delete" })); // confirm
    expect(screen.queryByText("Doomed")).toBeNull();
    expect(readProfiles().profiles).toHaveLength(0);
  });

  test("renaming a profile updates the manifest", async () => {
    const user = userEvent.setup();
    createProfile("Old", "default");
    render(<ProfileSelect onPlay={mock()} />);

    await user.click(screen.getByRole("button", { name: "Rename" }));
    const input = screen.getByLabelText("Rename profile");
    await user.clear(input);
    await user.type(input, "Fresh");
    await user.click(screen.getByRole("button", { name: "Save" }));

    expect(readProfiles().profiles[0].name).toBe("Fresh");
    expect(screen.getByText("Fresh")).toBeTruthy();
  });
});

import { boolean, integer, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core";
import { customType } from "drizzle-orm/pg-core";

/**
 * The online schema: better-auth's core tables (user/session/account/
 * verification, plus the anonymous plugin's isAnonymous and our skinId
 * additional field) and the game's own tables (worlds, memberships, invites).
 *
 * Shared by the Next.js app (Vercel, via node-postgres) and the game server
 * (Fly, via the same drizzle schema); tests run it against PGlite so CI needs
 * no database daemon. Migrations live in db/migrations (drizzle-kit).
 */

// drizzle's built-in bytea arrives in a newer major; this stays portable.
const bytea = customType<{ data: Uint8Array; notNull: false; default: false }>({
  dataType() {
    return "bytea";
  }
});

// ── better-auth core (column names follow better-auth's documented schema) ──

export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").notNull().default(false),
  image: text("image"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  /** Anonymous-plugin flag: a guest identity that can upgrade in place. */
  isAnonymous: boolean("is_anonymous"),
  /** Game profile: the player's skin palette id (additional field). */
  skinId: text("skin_id")
});

export const session = pgTable("session", {
  id: text("id").primaryKey(),
  expiresAt: timestamp("expires_at").notNull(),
  token: text("token").notNull().unique(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
  ipAddress: text("ip_address"),
  userAgent: text("user_agent"),
  userId: text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" })
});

export const account = pgTable("account", {
  id: text("id").primaryKey(),
  accountId: text("account_id").notNull(),
  providerId: text("provider_id").notNull(),
  userId: text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  accessToken: text("access_token"),
  refreshToken: text("refresh_token"),
  idToken: text("id_token"),
  accessTokenExpiresAt: timestamp("access_token_expires_at"),
  refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
  scope: text("scope"),
  password: text("password"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow()
});

export const verification = pgTable("verification", {
  id: text("id").primaryKey(),
  identifier: text("identifier").notNull(),
  value: text("value").notNull(),
  expiresAt: timestamp("expires_at").notNull(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow()
});

// ── game tables ──────────────────────────────────────────────────────────────

/**
 * One world. `kind` separates a cloud-synced single-player world (the blob is
 * the client's latest upload) from a multiplayer world (the blob is the game
 * server's authoritative persistence). One save blob either way: gzipped
 * SaveData JSON (v17 carries every player's slice).
 */
export const worlds = pgTable("worlds", {
  id: text("id").primaryKey(),
  ownerId: text("owner_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  kind: text("kind", { enum: ["sp-cloud", "mp"] }).notNull(),
  name: text("name").notNull(),
  seed: integer("seed").notNull(),
  worldType: text("world_type").notNull().default("default"),
  gameMode: text("game_mode").notNull().default("survival"),
  difficulty: text("difficulty").notNull().default("normal"),
  hardcore: boolean("hardcore").notNull().default(false),
  worldgenVersion: integer("worldgen_version").notNull(),
  saveVersion: integer("save_version"),
  saveBlob: bytea("save_blob"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow()
});

/** Who may play a world. The owner also has a row (role "owner") so one query lists a user's playable worlds. */
export const worldMembers = pgTable(
  "world_members",
  {
    worldId: text("world_id")
      .notNull()
      .references(() => worlds.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    role: text("role", { enum: ["owner", "member"] }).notNull(),
    joinedAt: timestamp("joined_at").notNull().defaultNow()
  },
  (table) => [uniqueIndex("world_members_pk").on(table.worldId, table.userId)]
);

/** Invite links: a random token, optionally expiring / use-limited. */
export const worldInvites = pgTable("world_invites", {
  id: text("id").primaryKey(),
  worldId: text("world_id")
    .notNull()
    .references(() => worlds.id, { onDelete: "cascade" }),
  token: text("token").notNull().unique(),
  createdBy: text("created_by")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  expiresAt: timestamp("expires_at"),
  maxUses: integer("max_uses"),
  uses: integer("uses").notNull().default(0),
  createdAt: timestamp("created_at").notNull().defaultNow()
});

