    .delete(schema.profiles)
    .where(and(eq(schema.profiles.id, profileId), eq(schema.profiles.ownerId, ownerId)))
    .returning({ id: schema.profiles.id });
  if (deleted.length === 0) return fail("not-found");
  return { ok: true };
}

